<?php
if(PHP_SAPI !== 'cli'){http_response_code(404);exit;}
$scratch=sys_get_temp_dir().'/mystep-router-'.bin2hex(random_bytes(6));mkdir($scratch,0700,true);
define('ROOT',$scratch.'/');define('APP',ROOT.'app/');define('CONFIG',ROOT.'config/');
mkdir(APP);mkdir(CONFIG);$lib=dirname(__DIR__, 2).'/lib/';$_SERVER['DOCUMENT_ROOT']='/';$_SERVER['SCRIPT_NAME']='/index.php';$_SERVER['REQUEST_TIME']=time();
require_once $lib.'myBase.class.php';require_once $lib.'myTrait.class.php';require_once $lib.'myReq.class.php';require_once $lib.'myFile.class.php';require_once $lib.'myRouter.class.php';
foreach(['myStep','Sample','CMS','test'] as $app){mkdir(APP.$app);file_put_contents(APP.$app.'/info.php','<?php return ["app"=>'.var_export($app,true).', "name"=>'.var_export($app,true).'];');}
class RouteSettings {public function merge($path){return $this;}}
class myStep {public static $started=0,$core='myStep';public static function getCore(){return self::$core;}public static function setPara(){self::$started++;}public static function checkBind($rule){}public static function info($message){throw new RuntimeException($message);} }
$ms_setting=new RouteSettings();$passed=$failed=0;
set_error_handler(function($severity,$message,$file,$line){if(error_reporting()&$severity)throw new ErrorException($message,0,$severity,$file,$line);});
function same($expected,$actual){if($expected!==$actual)throw new RuntimeException('Expected '.var_export($expected,true).'; got '.var_export($actual,true));}
function test($name,$run){global $passed,$failed;try{$run();$passed++;echo 'PASS '.$name.PHP_EOL;}catch(Throwable $e){$failed++;echo 'FAIL '.$name.': '.$e->getMessage().PHP_EOL;}}
function router($uri,$query='', $extra=[]){$_SERVER['REQUEST_URI']=$uri;$_SERVER['QUERY_STRING']=$query;$_SERVER['PATH_INFO']='';$_SERVER['ORIG_PATH_INFO']='';return new myRouter($extra+['mode'=>'rewrite']);}
test('query values preserve URLs, slashes and question marks',function(){$r=router('/console/','url=https://example.test/a//b?x=1');same('https://example.test/a//b?x=1',$_GET['url']);});
test('route matches the path without query parameters',function(){$r=router('/item/42?x=1','x=1');$called=null;$r->rule('/item/[int]',function($id)use(&$called){$called=$id;},'myStep');same(true,$r->check());same('42',$called);});
test('explicit application-prefixed routes run before app fallback',function(){$r=router('/CMS/special/7');$called=null;$r->rule('/CMS/special/[int]',function($id)use(&$called){$called=$id;},'CMS');same(true,$r->check());same('7',$called);});
test('bound route uses first matching rule',function(){$r=router('/42', '', ['url_fix'=>'/bound']);$called=null;$r->rule('/bound/[int]',function()use(&$called){$called='first';},'myStep');$r->rule('/bound/[any]',function()use(&$called){$called='last';},'myStep');same(true,$r->check());same('first',$called);});
test('direct route takes priority over prefixed route',function(){$r=router('/42','',['url_fix'=>'/bound']);$called=null;$r->rule('/bound/[any]',function()use(&$called){$called='bound';},'myStep');$r->rule('/[int]',function()use(&$called){$called='direct';},'myStep');$r->check();same('direct',$called);});
test('domain prefix comparison requires a segment boundary',function(){$r=router('/CMSExtra','',['url_fix'=>'/CMS']);same('CMS',$r->info['app']);same(['CMSExtra'],$r->info['path']);});
test('query parameters are decoded consistently',function(){$r=router('/item','name=a+b&token=a%3Db%3Dc');same('a b',$r->info['para']['name']);same('a=b=c',$r->info['para']['token']);});
test('middleware false stops final handler without app_missing',function(){$r=router('/guard/');$called=false;$r->rule('/guard/[any]',[function(){return false;},function()use(&$called){$called=true;}],'myStep');same(true,$r->check());same(false,$called);});
test('callable arrays are route handlers rather than middleware lists',function(){$target=new class{public $called=false;public function handle($id){$this->called=$id;}};$r=router('/array/7');$r->rule('/array/[int]',[$target,'handle'],'myStep');same(true,$r->check());same('7',$target->called);});
test('custom format preserves escaped and character-class parentheses',function(){$r=router('/literal/(');$r->format('paren','[(]');$value=null;$r->rule('/literal/[paren]',function($match)use(&$value){$value=$match;},'myStep');$r->check();same('(',$value);});
test('escaped literal parenthesis remains literal',function(){$r=router('/escaped/(');$r->format('open','\\(');$called=null;$r->rule('/escaped/[open]',function($value)use(&$called){$called=$value;},'myStep');same(true,$r->check());same('(',$called);});
test('explicit check path updates request context',function(){$r=router('/');$r->rule('/next/[int]',function(){},'myStep');same(true,$r->check('/next/9?x=1'));same('/next/9/',$r->route['p']);same('1',$r->info['para']['x']);});
test('shared API initializes selected core before dispatch',function(){myStep::$core='CMS';try{$r=router('/api/upload/json?core=CMS','core=CMS');$captured=null;$r->rule('/api/[str]/[any]',function($path)use(&$captured){$captured=$path;},'myStep');same(true,$r->check());same('CMS',$GLOBALS['info_app']['app']);same('myStep/upload/json/',$captured);}finally{myStep::$core='myStep';}});
test('named pipeline substitutions preserve legacy argument contract',function(){$r=router('/pipe/Alpha/rest');$GLOBALS['pipeline']=[];$r->format('camel','([A-Z][a-z]+)+');$r->rule('/pipe/[camel]/[any]',['pipelineGuard,$1','pipelineEnd'],'myStep');same(true,$r->check());same(['Alpha',true],$GLOBALS['pipeline'][0]);same(['Alpha/rest/',['ok']],$GLOBALS['pipeline'][1]);});
function pipelineGuard($capture,$previous){$GLOBALS['pipeline'][]=[$capture,$previous];return 'ok';}
function pipelineEnd($path,$results){$GLOBALS['pipeline'][]=[$path,$results];}
test('legacy query routes and PATH_INFO remain compatible',function(){foreach([['/index.php?/console/&x=1','/console/&x=1'],['/console/','console/&x=1'],['/index.php/console/?x=1','x=1']] as $case){$r=router($case[0],$case[1]);same('/console/',$r->route['p']);same('1',$_GET['x']);}});
test('registry without API list preserves existing rules',function(){$main=CONFIG.'registry1.php';$source=CONFIG.'source1.php';file_put_contents($main,'<?php $rule_list=["existing"=>[["/old/", "oldHandler"]]];');file_put_contents($source,'<?php $rule=[["/new/", "newHandler"]];');myRouter::checkRoute($main,$source,'new');include $main;same(true,isset($rule_list['existing']));});
test('registry refresh updates changed source and removes deleted APIs',function(){$main=CONFIG.'registry2.php';$source=CONFIG.'source2.php';file_put_contents($main,'<?php $rule_list=["app"=>[["/old/", "oldHandler"]]];$api_list=["app"=>["old"=>"oldAPI"]];');file_put_contents($source,'<?php $rule=[["/new/", "newHandler"]];');myRouter::checkRoute($main,$source,'app');include $main;same('/new/',$rule_list['app'][0][0]);same(false,isset($api_list['app']));});
test('unchanged registry is not rewritten',function(){$main=CONFIG.'registry3.php';$source=CONFIG.'source3.php';file_put_contents($source,'<?php $rule=[["/same/", "sameHandler"]];');myRouter::checkRoute($main,$source,'app');touch($main,1000000000);myRouter::checkRoute($main,$source,'app');clearstatcache(true,$main);same(1000000000,filemtime($main));});
test('concurrent registry updates preserve all applications',function()use($lib){$main=CONFIG.'concurrent.php';$worker=ROOT.'registry-worker.php';$code='<?php $_SERVER["DOCUMENT_ROOT"]="/";';foreach(['myBase','myTrait','myFile','myRouter'] as $class)$code.='require '.var_export($lib.$class.'.class.php',true).';';$code.='myRouter::checkRoute($argv[1],$argv[2],$argv[3]);';file_put_contents($worker,$code);$processes=[];for($i=0;$i<4;$i++){$source=CONFIG.'concurrent'.$i.'.php';file_put_contents($source,'<?php usleep(100000);$rule=[["/app'.$i.'/", "handler"]];');$pipes=[];$process=proc_open([PHP_BINARY,$worker,$main,$source,'app'.$i],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);$processes[]=[$process,$pipes];}foreach($processes as [$process,$pipes]){fclose($pipes[0]);$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);same(0,proc_close($process));same('',$err);}include $main;same(4,count($rule_list));});
test('custom formats are scoped to their owning application',function(){$file=CONFIG.'formats.php';file_put_contents($file,'<?php $format_list=["one"=>["value"=>"[0-9]+"],"two"=>["value"=>"[a-z]+"]];$rule_list=["one"=>[["/number/[value]","handler"]],"two"=>[["/word/[value]","handler"]]];');$r=router('/');$r->setRules($file);same(1,preg_match($r->rules[0]['regex'],'/number/42'));same(0,preg_match($r->rules[0]['regex'],'/number/word'));same(1,preg_match($r->rules[1]['regex'],'/word/letters'));});
test('public file resolver rejects traversal, encoded traversal and symlink escapes',function(){mkdir(ROOT.'public');file_put_contents(ROOT.'secret.php','sensitive fixture');file_put_contents(ROOT.'public/good.js','good');symlink(ROOT.'secret.php',ROOT.'public/link.js');same(realpath(ROOT.'public/good.js'),myFile::resolveWithin(ROOT.'public','good.js'));foreach(['../secret.php','%2e%2e/secret.php','..\\secret.php','link.js'] as $path)same(false,myFile::resolveWithin(ROOT.'public',$path));});
function removeTree($path){if(is_link($path)||is_file($path)){unlink($path);return;}foreach(new FilesystemIterator($path) as $file)removeTree($file->getPathname());rmdir($path);}
removeTree($scratch);echo "Passed: $passed; Failed: $failed\n";exit($failed?1:0);
